  from jsonb_to_recordset($seed$[{"code":"standard","label":"Standard delivery","amount":25000,"freeOver":1200000,"minDays":2,"maxDays":5,"cashOnDelivery":true},{"code":"express","label":"Express delivery (Karachi, Lahore, Islamabad)","amount":60000,"freeOver":null,"minDays":1,"maxDays":2,"cashOnDelivery":true}]$seed$::jsonb) as r(code text, label text, amount bigint, "freeOver" bigint, "minDays" integer, "maxDays" integer, "cashOnDelivery" boolean);

insert into public.tax_rates (store_id, country, province, label, basis_points, inclusive)
