insert into public.promotions (id, store_id, code, title, conditions, actions, starts_at, ends_at, usage_limit, per_customer_limit, times_used, active, combinable)
  select id, '00000000-0000-4000-8000-000000000001', code, title, conditions, actions, "startsAt", "endsAt", "usageLimit", "perCustomerLimit", "timesUsed", active, combinable
  from jsonb_to_recordset($seed$[{"id":"70000000-0000-4000-8000-000000000001","storeId":"00000000-0000-4000-8000-000000000001","code":"WELCOME10","title":"10% off your first order","conditions":[{"type":"first_order"}],"actions":[{"type":"percent_off_order","basisPoints":1000}],"startsAt":null,"endsAt":null,"usageLimit":null,"perCustomerLimit":1,"timesUsed":0,"active":true,"combinable":false},{"id":"70000000-0000-4000-8000-000000000002","storeId":"00000000-0000-4000-8000-000000000001","code":"PRELOVED500","title":"Rs. 500 off pre-loved pairs over Rs. 10,000","conditions":[{"type":"product_kind","kind":"preloved"},{"type":"subtotal_at_least","amount":1000000}],"actions":[{"type":"fixed_off_order","amount":50000}],"startsAt":null,"endsAt":null,"usageLimit":500,"perCustomerLimit":null,"timesUsed":0,"active":true,"combinable":true}]$seed$::jsonb)
    as r(id uuid, code text, title text, conditions jsonb, actions jsonb, "startsAt" timestamptz, "endsAt" timestamptz, "usageLimit" integer, "perCustomerLimit" integer, "timesUsed" integer, active boolean, combinable boolean);

insert into public.feature_flags (store_id, key, description, enabled, customer_groups)
  select '00000000-0000-4000-8000-000000000001', key, description, enabled, array(select jsonb_array_elements_text("customerGroups"))
  from jsonb_to_recordset($seed$[{"key":"b2b-pricing","description":"Wholesale price list and quote requests for approved trade accounts.","enabled":false,"customerGroups":["wholesale"]},{"key":"multi-currency-display","description":"Show approximate prices in USD / AED / GBP next to PKR.","enabled":false,"customerGroups":null},{"key":"stripe-payments","description":"Card payments through Stripe (needs STRIPE_SECRET_KEY).","enabled":false,"customerGroups":null},{"key":"express-delivery","description":"Offer the express delivery rate at checkout.","enabled":true,"customerGroups":null}]$seed$::jsonb)
    as r(key text, description text, enabled boolean, "customerGroups" jsonb);

insert into public.pages (store_id, slug, title, description, blocks, seo, published, updated_at)
  select '00000000-0000-4000-8000-000000000001', slug, title, description, blocks, coalesce(seo, '{}'), true, "updatedAt"
  from jsonb_to_recordset($seed$[{"slug":"about","title":"About Sole Drop","description":"New and pre-loved footwear from brands you love.","updatedAt":"2026-11-03T00:00:00.000Z","seo":{},"blocks":[{"type":"paragraph","text":"Sole Drop sells brand-new and pre-loved footwear from the brands you love — ASICS, Nike, adidas, HOKA, Brooks and more."},{"type":"paragraph","text":"Every brand-new pair is sourced from authorised distributors. Every pre-loved pair is inspected, cleaned, graded and photographed, so the pair you see is the pair you get."},{"type":"cta","text":"Fresh finds. Fresh steps.","label":"Shop new arrivals","href":"/collections/new-arrivals"}]},{"slug":"our-story","title":"Our Story","description":"Why we started Sole Drop.","updatedAt":"2026-11-03T00:00:00.000Z","seo":{},"blocks":[{"type":"paragraph","text":"Sole Drop started in Karachi with a simple idea: great shoes shouldn't be hard to find, and good shoes shouldn't go to waste."},{"type":"paragraph","text":"So we built one place for new releases and second-chance pairs — honest about condition, quick to deliver, and easy to return."}]}]$seed$::jsonb) as r(slug text, title text, description text, blocks jsonb, seo jsonb, "updatedAt" timestamptz);

insert into public.faqs (id, store_id, category, question, answer, position)
  select id, '00000000-0000-4000-8000-000000000001', category, question, answer, position
  from jsonb_to_recordset($seed$[{"id":"80000000-0000-4000-8000-000000000001","category":"Shopping & sizing","question":"What does Soledrop sell?","answer":"We offer Brand New shoes and individually assessed Pre-Loved shoes. Both can appear in the same shopping cart, and each item is labeled by category.","position":0},{"id":"80000000-0000-4000-8000-000000000002","category":"Shopping & sizing","question":"Can I order Brand New and Pre-Loved shoes together?","answer":"Yes, where both items are in stock and eligible for the same checkout. We review any later return request for each product separately.","position":1},{"id":"80000000-0000-4000-8000-000000000003","category":"Shopping & sizing","question":"Are all shoes the same fit in EU size 42, for example?","answer":"Not necessarily. Shoe sizing varies by brand and model. Use the stated EU size and any measurements provided, or ask support before purchasing.","position":2},{"id":"80000000-0000-4000-8000-000000000004","category":"Shopping & sizing","question":"Which payment methods are accepted?","answer":"Only payment methods displayed at checkout are currently active. They may include COD or supported prepaid options as configured.","position":3},{"id":"80000000-0000-4000-8000-000000000005","category":"Shopping & sizing","question":"Can I cancel after placing an order?","answer":"Contact us immediately. We aim to help before dispatch; after dispatch, the normal return process applies.","position":4},{"id":"80000000-0000-4000-8000-000000000006","category":"Pre-Loved shoes","question":"Are Pre-Loved shoes new?","answer":"No. Even a Like New pair belongs to our Pre-Loved collection. Brand New is a separate category for unused footwear.","position":5},{"id":"80000000-0000-4000-8000-000000000007","category":"Pre-Loved shoes","question":"How do I know the condition of a Pre-Loved pair?","answer":"Check the actual product photos, condition grade, description, size information, and flaw notes. Our five Pre-Loved grades are Like New, Premium, Excellent, Very Good, and Minor Issue.","position":6},{"id":"80000000-0000-4000-8000-000000000008","category":"Pre-Loved shoes","question":"Do Pre-Loved shoes come with the original box?","answer":"Only if the product listing says so. Packaging and included accessories may vary from one pair to another.","position":7},{"id":"80000000-0000-4000-8000-000000000009","category":"Pre-Loved shoes","question":"Is every Pre-Loved pair cleaned?","answer":"We disclose our actual preparation process and do not promise medical sterilization. If you need information about how a particular pair was prepared, ask support.","position":8},{"id":"80000000-0000-4000-8000-000000000010","category":"Pre-Loved shoes","question":"Are Pre-Loved shoes guaranteed to last for a set time?","answer":"No fixed remaining lifespan can be guaranteed. Prior wear, storage, materials, and age affect durability. This does not remove rights relating to an undisclosed defect or misrepresentation.","position":9},{"id":"80000000-0000-4000-8000-000000000011","category":"Delivery & tracking","question":"How much is delivery?","answer":"The delivery amount is shown before order confirmation. Standard shipping: {standardShipping}.","position":10},{"id":"80000000-0000-4000-8000-000000000012","category":"Delivery & tracking","question":"How long will delivery take?","answer":"Our standard is one to two working days to prepare an order, followed by an estimated three to seven working days after dispatch.","position":11},{"id":"80000000-0000-4000-8000-000000000013","category":"Delivery & tracking","question":"How can I track an order?","answer":"We share a tracking reference or status update when our chosen courier provides it. Contact us with your order number if you need assistance.","position":12},{"id":"80000000-0000-4000-8000-000000000014","category":"Returns, exchanges & refunds","question":"Can I exchange shoes if the size is wrong?","answer":"Our seven-day policy allows eligible indoor try-on exchanges or returns for both categories. Brand New shoes must remain unused, while Pre-Loved shoes must remain in the condition received. A matching Pre-Loved replacement cannot be guaranteed.","position":13},{"id":"80000000-0000-4000-8000-000000000015","category":"Returns, exchanges & refunds","question":"Can I return a Pre-Loved pair because I changed my mind?","answer":"Yes, when you contact us within seven calendar days of delivery and the item qualifies for a preference return. Customer-paid return postage normally applies for this reason.","position":14},{"id":"80000000-0000-4000-8000-000000000016","category":"Returns, exchanges & refunds","question":"What if the shoes are damaged or different from the description?","answer":"Contact support promptly with photographs and your order number. We separately investigate wrong items, undisclosed faults, and materially misleading descriptions. Mandatory legal remedies are not removed by the voluntary return conditions.","position":15},{"id":"80000000-0000-4000-8000-000000000017","category":"Returns, exchanges & refunds","question":"How do refunds work for COD orders?","answer":"For an approved eligible refund, we can arrange a verified bank transfer or another agreed secure method. We will explain the destination and timing before processing.","position":16},{"id":"80000000-0000-4000-8000-000000000018","category":"Contact us","question":"How do I contact Soledrop?","answer":"Email {supportEmail}, call or WhatsApp {contactNumber}, or use our website contact form at {contactPage}.","position":17}]$seed$::jsonb) as r(id uuid, category text, question text, answer text, position integer);

insert into public.search_synonyms (id, store_id, term, synonyms)
  select id, '00000000-0000-4000-8000-000000000001', term, array(select jsonb_array_elements_text(synonyms))
  from jsonb_to_recordset($seed$[{"id":"60000000-0000-4000-8000-000000000001","term":"sneakers","synonyms":["trainers","kicks","joggers"]},{"id":"60000000-0000-4000-8000-000000000002","term":"running","synonyms":["runners","jogging"]},{"id":"60000000-0000-4000-8000-000000000003","term":"pre-loved","synonyms":["preloved","used","second hand","thrift"]},{"id":"60000000-0000-4000-8000-000000000004","term":"new balance","synonyms":["nb"]},{"id":"60000000-0000-4000-8000-000000000005","term":"grey","synonyms":["gray"]},{"id":"60000000-0000-4000-8000-000000000006","term":"sketchers","synonyms":["skechers"]}]$seed$::jsonb) as r(id uuid, term text, synonyms jsonb);
